CREATE FUNCTION pao.gen_pfms_data(ddo_offid character varying, acct_date date) RETURNS TABLE(ddo_office_id character varying, functional_head character varying, object_head character varying, grant_no character varying, category character varying, remarks character varying, receipt_payment character varying, sign character varying, amount character varying)
    LANGUAGE sql
    AS $$

  
SELECT 
    offi.ddo_code  AS DDOCode,
    substring(m.hoa,1,13) as Functional_head,
    substring(m.hoa,14,2) as Object_head,
    m.grant_no ,m.category ,'DoP Daily Account' as Remarks,
    case when lat.each_item->>'credit_or_debit' = 'R' then 'T' else 'F' end as receipt_payment
    ,
      case when m.value_sign  = 'N' then '-' else '+' end as Sign
    ,
    CASE 
        WHEN lat.each_item->>'credit_or_debit' = 'R' THEN SUM((lat.each_item->>'bo_amount')::numeric + (lat.each_item->>'so_amount')::numeric + (lat.each_item->>'ho_amount')::numeric)
        ELSE 
SUM((lat.each_item->>'bo_amount')::numeric + (lat.each_item->>'so_amount')::numeric + (lat.each_item->>'ho_amount')::numeric) 
  end
  AS Amount
FROM 
    pao.kafka_cash_book AS c 
CROSS JOIN 
    json_array_elements(c.details) AS lat(each_item)
LEFT JOIN 
    pao.ddo_master AS offi ON c.office_id = offi.ddo_office_id 
LEFT JOIN 
    pao.account_hoa_mapping AS m ON lat.each_item->>'account_code' = m.account_code
WHERE 
offi.ddo_code = ddo_offid and
    c.business_date =  CAST(acct_date AS DATE)
GROUP BY 
    offi.ddo_code,substring(m.hoa,1,13) ,
    substring(m.hoa,14,2), m.grant_no ,m.category ,m.value_sign 
    , lat.each_item->>'credit_or_debit'
   
UNION 

SELECT 
    offi.ddo_code AS DDOCode,
 substring(a.hoa,1,13) as Functional_head,
    substring(a.hoa,14,2) as Object_head,
     a.grant_no ,a.category ,'DoP Daily Account' as Remarks,
 case when lat.each_item->>'credit_or_debit' = 'R' then 'T' else 'F' end as receipt_payment,
   case when a.value_sign  = 'N' then '-' else '+' end as Sign
    ,
  sum(  CASE 
        WHEN lat.each_item->>'credit_or_debit'  = 'R' then c.opening_bal  
        ELSE c.closing_bal 
    end) AS Amount
FROM 

     pao.kafka_cash_book AS c 
CROSS JOIN 
    json_array_elements(c.details) AS lat(each_item) 
LEFT JOIN 
    pao.ddo_master AS offi ON c.office_id = offi.ddo_office_id 
    inner join 
    pao.account_hoa_mapping a on a.receipt_payment = lat.each_item->>'credit_or_debit'
WHERE 
   
   offi.ddo_code = ddo_offid and
    c.business_date =  CAST(acct_date AS DATE)
   and  a.hoa = '867100102000000' 
GROUP BY 
    offi.ddo_code, 
    substring(a.hoa,1,13) ,  a.grant_no ,a.category ,
    substring(a.hoa,14,2) , a.value_sign ,
   lat.each_item->>'credit_or_debit';

$$;


--
-- TOC entry 257 (class 1255 OID 18269)
-- Name: gen_pfms_te_data(character varying); Type: FUNCTION; Schema: pao; Owner: -
--

CREATE FUNCTION pao.gen_pfms_te_data(te_id character varying) RETURNS TABLE(ddo_office_id character varying, functional_head character varying, object_head character varying, grant_no character varying, category character varying, remarks character varying, receipt_payment character varying, sign character varying, amount character varying)
    LANGUAGE sql
    AS $$

  
SELECT 
    c.ddo_code  AS DDOCode,
    substring(c.hoa ,1,13) as Functional_head,
    substring(c.hoa,14,2) as Object_head,
    m.grant_no ,m.category ,'DoP Transfer Entries' as Remarks,
    case when m.receipt_payment = 'R' then 'T' else case when m.receipt_payment = 'P' then 'F' end end as receipt_payment
    ,
         CASE
        WHEN SIGN(c.transfer_amount) >= 0 THEN '+'
        WHEN SIGN(c.transfer_amount) < 0 THEN '-'
    end
 as Sign
    ,
c.transfer_amount 
  AS Amount
FROM 
    pao.transfer_entry  AS c 

LEFT JOIN 
   (select distinct grant_no , category , hoa,receipt_payment from pao.account_hoa_mapping) AS m
   ON c.hoa = m.hoa and 
    m.receipt_payment = (case when c.transfer_type = 'C' then  'R' else 'P'end)
    WHERE c.transfer_entry_id = te_id

GROUP BY 
     c.ddo_code,substring(c.hoa,1,13) ,
    substring(c.hoa,14,2), m.grant_no ,m.category ,c.transfer_amount
    , m.receipt_payment;
   


$$;


--
-- TOC entry 270 (class 1255 OID 141012)
-- Name: generate_pfms_xml(json); Type: FUNCTION; Schema: pao; Owner: -
--

CREATE FUNCTION pao.generate_pfms_xml(cb_params json) RETURNS TABLE(uniqueid character varying, xml_output1 xml)
    LANGUAGE plpgsql
    AS $$
DECLARE
    xml_output XML;
    xml_output1 XML := NULL;
    input_param JSON;
   uniqueid varchar(24);
begin
        
    uniqueid := (SELECT 'TE-'||(cb_params->0->>'pao_code') || TO_CHAR(CURRENT_TIMESTAMP, 'YYYYMMDDHH24MISS'));
   
   
    FOR input_param IN SELECT * FROM json_array_elements(cb_params) LOOP
       xml_output := xmlelement(name "TEMaster",
    xmlattributes(
    uniqueid     AS "UniqueIdentifier",
        'Others' AS "InstrumentType",
        (input_param->>'fin_year') AS "FinancialYear",
        'Test' AS "Remarks",
        (input_param->>'cb_date') AS "TEDate"
    ),
    xmlelement(name "TEAccountingDetails",
        (SELECT xmlagg(
            xmlelement(name "Account",
                xmlattributes(
                    ddo_office_id AS "DDOCode",
                    grant_no AS "GrantNo",
                    functional_head AS "FunctionalHead",
                    object_head AS "ObjectHead",
                    category AS "Category",
                    sign AS "Sign",
                    amount AS "Amount",
                    remarks AS "Remarks",
                    receipt_payment AS "Transfer"
                )
            )
        )
        FROM pao.gen_pfms_data((input_param->>'office_id'), 
            (input_param->>'cb_date')::DATE))
    )
);

        -- Concatenate xml_output to xml_output1 using xmlconcat()
        xml_output1 := xmlconcat(xml_output1, xml_output);
    END LOOP;

    -- Construct the final XML structure
    xml_output1 := xmlelement(name "x:Envelope",
                    xmlelement(name "x:Header",
                        xmlelement(name "tem:Password", 'dummy@321!'),
                        xmlelement(name "tem:UserName", 'dummywebsvc')
                    ),
                    xmlelement(name "x:Body",
                        xmlelement(name "tem:RequestTransferEntryDataMessage"),
                        xmlelement(name "TransferEntry",
                            xmlattributes('http://webservices.pfms.nic.in/PFMSExternalWebService.xsd' AS xmlns, 
                                'DepartmentOfPosts' AS "RequestSource", (cb_params->0->>'pao_code') AS "PaoCode"),
--                            xmlelement(name ""TEMaster"",
--                                xmlattributes(uniqueid AS ""UniqueIdentifier"", 'Others' AS ""InstrumentType"", 
--                                    (cb_params->0->>'fin_year') AS ""FinancialYear"", 'Test' AS ""Remarks"", TO_CHAR(CURRENT_DATE, 'YYYY-MM-DD') AS ""TEDate""),
--                                xmlelement(name ""InstrumentDetails"",
--                                    xmlattributes('101879' AS ""InstrumentDDOCode"", '101010' AS ""InstrumentNumber"", 
--                                        (cb_params->0->>'fin_year') AS ""InstrumentFinancialYear"", '2020-04-01' AS ""InstrumentDate"")
--                                ),
                                xml_output1
--                            )
                        )
                    )
                );
         
         insert  into pao.pfms_xml(te_identifier, pao_code, pfms_xml_data)values(uniqueid,(cb_params->0->>'pao_code'),xml_output1);
--              insert  into pao.pfms_xml(te_identifier, pao_code, xml_data) values (uniqueid,'dsffdd',xml_output1);  
              FOR input_param IN SELECT * FROM json_array_elements(cb_params) LOOP
             UPDATE pao.pfms_main AS a1
SET h_pfms_generation_flag = true , xml_unique_id = uniqueid 
FROM pao.ddo_master AS a
-- INNER JOIN pao.office_master AS b ON a.ddo_office_id = b.office_id
WHERE a1.ddo_code = a.ddo_code
AND a.ddo_code = (input_param->>'office_id')
AND a1.business_date = (input_param->>'cb_date')::DATE;

   END LOOP;

   RETURN QUERY SELECT uniqueid, xml_output1;
END;
$$;


--
-- TOC entry 260 (class 1255 OID 141018)
-- Name: generate_te_xml(json); Type: FUNCTION; Schema: pao; Owner: -
--

CREATE FUNCTION pao.generate_te_xml(te_params json) RETURNS TABLE(uniqueid character varying, xml_output1 xml)
    LANGUAGE plpgsql
    AS $$
DECLARE
    xml_output XML;
    xml_output1 XML := NULL;
    input_param JSON;
   uniqueid varchar(24);
begin
        
    uniqueid := (SELECT 'TE-'||(te_params->0->>'pao_code') || TO_CHAR(CURRENT_TIMESTAMP, 'YYYYMMDDHH24MISS'));
   
   
    FOR input_param IN SELECT * FROM json_array_elements(te_params) LOOP
       xml_output := xmlelement(name "TEMaster",
    xmlattributes(
    uniqueid     AS "UniqueIdentifier",
        'Others' AS "InstrumentType",
        (input_param->>'fin_year') AS "FinancialYear",
        'Test' AS "Remarks",
        (input_param->>'te_date') AS "TEDate"
    ),
    xmlelement(name "TEAccountingDetails",
        (SELECT xmlagg(
            xmlelement(name "Account",
                xmlattributes(
                    ddo_office_id AS "DDOCode",
                    grant_no AS "GrantNo",
                    functional_head AS "FunctionalHead",
                    object_head AS "ObjectHead",
                    category AS "Category",
                    sign AS "Sign",
                    amount AS "Amount",
                    remarks AS "Remarks",
                    receipt_payment AS "Transfer"
                )
            )
        )
        FROM pao.gen_pfms_te_data(input_param->>'te_id')
    ))
);

       
        xml_output1 := xmlconcat(xml_output1, xml_output);
    END LOOP;
--
--    -- Construct the final XML structure
    xml_output1 := xmlelement(name "x:Envelope",
                    xmlelement(name "x:Header",
                        xmlelement(name "tem:Password", 'dummy@321!'),
                        xmlelement(name "tem:UserName", 'dummywebsvc')
                    ),
                    xmlelement(name "x:Body",
                        xmlelement(name "tem:RequestTransferEntryDataMessage"),
                        xmlelement(name "TransferEntry",
                            xmlattributes('http://webservices.pfms.nic.in/PFMSExternalWebService.xsd' AS xmlns, 
                                'DepartmentOfPosts' AS "RequestSource", (te_params->0->>'pao_code') AS "PaoCode"),
--                                                           ),
                                xml_output1
--                            )
                        )
                    )
                );
         
         insert  into pao.pfms_xml(te_identifier, pao_code, pfms_xml_data)values(uniqueid,(te_params->0->>'pao_code'),xml_output1);

        
        FOR input_param IN SELECT * FROM json_array_elements(te_params) LOOP
             UPDATE pao.transfer_entry  AS a1
set xml_generation_status = 'generated',xml_unique_id = uniqueid  where transfer_entry_id =  (input_param->>'te_id');


   END LOOP;

   RETURN QUERY SELECT uniqueid, xml_output1;
END;
$$;
